/* FitFirst prototype — the owner's view: results, clearance controls, demand gaps, team, pilot scorecard */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES, CH = FF.chart;
  const I = { days: 21 };
  const perDay = (days, fn) => { const out = []; for (let d = days - 1; d >= 0; d--) { const t = new Date(Date.now() - d * FF.DAY); t.setHours(0, 0, 0, 0); out.push({ l: FF.fmtDate(t), v: fn(t.getTime(), t.getTime() + FF.DAY) }); } return out; };

  FF.page('insights', { title: 'Results', icon: 'chart', roles: R.MGR, render: () => { const m = FF.metrics(I.days), db = FF.db, det = FF.sum(m.S.filter((s) => s.visit), (s) => s.total), prob = det * 1.18;
    const vis = perDay(I.days, (a, b) => db.visits.filter((v) => v.at >= a && v.at < b && v.status !== 'BROWSING').length), buy = perDay(I.days, (a, b) => db.visits.filter((v) => v.at >= a && v.at < b && v.status === 'PURCHASED').length), aged = perDay(I.days, (a, b) => FF.sum(db.sales.filter((s) => s.at >= a && s.at < b).flatMap((s) => s.lines.filter((l) => l.aged)), (l) => l.price * l.qty - l.disc));
    const rated = m.V.filter((v) => v.rating), fmax = Math.max(1, m.funnel[0][1]);
    return `<div class="ph1"><div><h1>Results</h1><p>What FitFirst did for the shop. Every number here comes from a bill, a scan or a staff tap — nothing is estimated unless it says so. ${U.demo('Demo numbers')}</p></div><div class="row wrap">${U.seg('i-days', [[7, '7 days'], [21, 'Since go-live'], [30, '30 days']], I.days)}<button class="btn" data-act="i-wa">${FF.icon('wa')} Daily summary</button></div></div>
      <div class="grid g3">${U.kpi('Aged stock cleared', FF.inrK(m.agedCleared), `${FF.inrK(m.agedAttr)} of it through a FitFirst recommendation`, { info: 'Sum of sale lines that were past their fresh window on the day they sold, at the price actually charged.' })}
        ${U.kpi('Clearance lift vs control group', m.lift == null ? '<span style="font-size:19px">Not enough data yet</span>' : (m.lift >= 0 ? '+' : '') + Math.round(m.lift * 100) + '%', m.lift == null ? `Control group has ${m.nHold} visits; 20 needed` : `Aged piece bought in ${(m.rb * 100).toFixed(1)}% of ${m.nBoost} boosted visits vs ${(m.rh * 100).toFixed(1)}% of ${m.nHold} control visits`, { info: 'About 1 in 10 shoppers get picks with no old-stock nudge. Comparing the two groups measures the effect instead of claiming it.' })}
        ${U.kpi('Bought a recommended piece', FF.pct(m.recBuy, m.sessions), `${m.recBuy} of ${m.sessions} consultations`, { info: 'Distinct consultations where at least one recommended piece was bought, divided by all consultations. One shopper buying three pieces counts once.' })}
        ${U.kpi('Consultations', m.sessions, `${m.abandoned} left midway · ${m.usage == null ? 'footfall not logged' : Math.round(m.usage * 100) + '% of logged footfall'}`)}${U.kpi('Time to purchase', Math.round(m.mins) + ' min', 'from first answer to bill', { info: 'Average minutes between the start of a consultation and its sale, for visits that ended in a purchase.' })}${U.kpi('Pieces tried per purchase', m.tried.toFixed(1), 'fewer means less staff time per sale')}</div>
      <div class="grid g2 stack sec"><div class="card"><h3>Consultations and purchases per day</h3><div class="mt12">${CH.line([{ name: 'Consultations', c: CH.ink, pts: vis.map((x) => x.v) }, { name: 'Ended in a purchase', c: CH.brass, pts: buy.map((x) => x.v), dash: true }], vis.map((x) => x.l), { label: 'Consultations and purchases per day' })}</div></div>
        <div class="card"><h3>Aged stock cleared per day (₹)</h3><div class="mt12">${CH.bars(aged, { fmt: FF.inrK, label: 'Aged stock cleared per day' })}</div></div></div>
      <div class="grid g3 sec"><div class="card"><h3>From shown to bought</h3><p class="small muted">Pieces, across all consultations</p><div class="funnel mt12">${m.funnel.map(([l, v]) => `<div><span>${l}</span><i style="width:${(v / fmax) * 100}%"></i><span class="num right b">${v} <span class="muted" style="font-weight:400">${FF.pct(v, fmax)}</span></span></div>`).join('')}</div></div>
        <div class="card"><h3>Why pieces were rejected</h3><p class="small muted">One tap by staff after a fitting</p><div class="mt12">${m.reasons.length ? CH.hbar(m.reasons.slice(0, 6)) : '<p class="small muted">No rejections recorded in this period.</p>'}</div></div>
        <div class="card"><h3>How sales were linked</h3><p class="small muted">Only proven links count in the headline</p><dl class="kv mt12" style="grid-template-columns:1fr max-content">${['QR_SCAN', 'HANDOFF_CODE', 'STAFF_LINKED'].map((a) => `<dt>${{ QR_SCAN: 'QR scanned at billing', HANDOFF_CODE: 'Code typed on the bill', STAFF_LINKED: 'Linked by staff' }[a]}</dt><dd class="num right">${m.S.filter((s) => s.attribution === a).length}</dd>`).join('')}</dl><hr><div class="small">Linked revenue <b>${FF.inrK(det)}</b><br><span class="muted">Up to ${FF.inrK(prob)} if likely-but-unproven matches are included (recommended piece sold within 3 hours). Shown as a range only.</span></div><hr><div class="small">Shopper rating <b>${rated.length ? (FF.sum(rated, (v) => v.rating) / rated.length).toFixed(1) + ' / 5' : '—'}</b> <span class="muted">from ${rated.length} ratings</span></div></div></div>`; } });
  FF.act('i-days', (d) => { I.days = +d.v; FF.render(); });
  FF.act('i-wa', () => { const m = FF.metrics(1), g = FF.db.gaps.filter((x) => x.status === 'open')[0], w = FF.db.settings.whatsapp; FF.modal({ title: 'WhatsApp daily summary', sub: w.summary ? `Sent to ${w.to} at ${w.time} every day` : 'Currently switched off', size: 'narrow', body: `<div class="wa" style="background:#E7F5E4;border:1px solid #BFE0B8;border-radius:12px 12px 12px 2px;padding:10px 12px"><b>${esc(FF.store().name)} · today</b><br>👥 ${m.sessions} consultations · ${m.bought} bought<br>✅ ${m.recBuy} bought a recommended piece<br>📦 Aged stock cleared: <b>${FF.inr(m.agedCleared)}</b><br>${g ? `🛒 Asked for but missing: ${g.count} wanted ${FF.catName(g.cat).toLowerCase()} in ${g.size}<br>` : ''}⭐ Top seller: ${esc((FF.db.staff.find((s) => s.role === 'STAFF') || {}).name)}<br><span class="tiny" style="color:#2A5680">Open dashboard →</span></div><p class="tiny muted mt12">One utility message a day, about ₹0.15. Owner opt-in only.</p>`, footer: `<a class="btn" href="#/settings/notify">Settings</a><button class="btn btn-p" data-act="i-wa-send">Send a test now</button>` }); });
  FF.act('i-wa-send', () => { FF.closeOverlay(); FF.toast('Test summary sent (simulated)', 'ok'); });

  /* ---------- clearance ---------- */
  const CL = { shopper: 0 };
  const SHOPPERS = [['Festive saree · warm undertone · petite', { dept: 'WOMEN', cats: ['saree'], occasion: 'festive', budget: 0, sizes: {}, height: 'petite', likes: [], dislikes: [], tone: 5, undertone: 'warm', contrast: 'medium', goals: [] }], ['Wedding outfit · cool undertone · size M', { dept: 'WOMEN', cats: ['lehenga', 'anarkali', 'kurta_set'], occasion: 'wedding', budget: 0, sizes: { ALPHA: 'M' }, height: 'average', likes: [], dislikes: [], tone: 4, undertone: 'cool', contrast: 'high', goals: ['define_waist'] }], ["Men's festive · size L", { dept: 'MEN', cats: [], occasion: 'festive', budget: 6000, sizes: { ALPHA: 'L' }, height: 'tall', likes: [], dislikes: [], tone: 6, undertone: 'neutral', contrast: 'medium', goals: ['look_taller'] }]];
  FF.act('set-lambda', (d) => { FF.db.settings.lambda = d.v; FF.audit('Clearance priority → ' + FF.cap(d.v), 'Merch policy', 'λ ' + FF.engine.LAMBDA[d.v]); FF.save(); FF.render(); FF.toast('Clearance priority: ' + FF.cap(d.v), 'ok'); });
  FF.page('clearance', { title: 'Clearance', icon: 'bolt', roles: R.MGR, render: () => { const s = FF.db.settings, db = FF.db, aged = db.products.filter((p) => p.status === 'LIVE' && FF.ageBand(p) !== 'fresh' && FF.stockTotal(p) > 0), val = FF.sum(aged, (p) => p.mrp * FF.stockTotal(p));
    const pr = SHOPPERS[CL.shopper][1], off = FF.engine.recommend(pr, { lambda: 'off' }).all.slice(0, 5), on = FF.engine.recommend(pr, {}).all.slice(0, 5);
    const col = (list, title) => `<div><h4>${title}</h4><div class="col gap6 mt8">${list.map((i, k) => `<div class="row" style="padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:${i.boosted ? 'var(--brass-bg)' : 'var(--paper)'}"><b class="muted" style="width:14px">${k + 1}</b><div class="thumb" style="width:30px;height:38px">${FF.garment(i.p)}</div><span class="grow small"><b>${esc(i.p.name)}</b><br><span class="muted">suits ${i.S.toFixed(2)} · ${i.age} d${i.boosted ? ' · nudged +' + i.boost.toFixed(3) : ''}</span></span></div>`).join('') || '<p class="small muted">No eligible pieces.</p>'}</div></div>`;
    const byBand = Object.entries(FF.groupBy(aged, (p) => FF.TAX.groups[FF.TAX.cats[p.cat].group].name)).map(([l, a]) => ({ l, v: FF.sum(a, (p) => p.mrp * FF.stockTotal(p)), sub: a.length + ' styles' })).sort((a, b) => b.v - a.v);
    return `<div class="ph1"><div><h1>Clearance</h1><p>Older stock is shown first to the shoppers it suits. You choose how strong the nudge is; the guardrails below cannot be switched off.</p></div></div>
      <div class="split"><div class="card"><h3>Clearance priority</h3><div class="mt12">${U.seg('set-lambda', [['off', 'Off'], ['low', 'Low'], ['medium', 'Medium'], ['high', 'High']], s.lambda)}</div><ul class="small mt16" style="margin:0;padding-left:18px;display:flex;flex-direction:column;gap:6px"><li>An aged piece is only nudged if it already suits the shopper nearly as well as the best match.</li><li>The nudge is always smaller than 0.10, so it can <b>never outrank a piece that suits clearly better</b>.</li><li>At most <select data-change="cl-max" style="width:auto;min-height:28px;padding:0 6px;display:inline-block" aria-label="Maximum nudged pieces">${[1, 2, 3].map((n) => `<option ${s.maxBoost === n ? 'selected' : ''}>${n}</option>`).join('')}</select> nudged pieces in any shopper's top five.</li><li>Exposure is spread: a piece shown a lot this week is nudged less, so not every shopper sees the same saree.</li><li>${s.holdout}% of shoppers get no nudge at all — that control group is how the lift is measured.</li></ul>
        <hr><div class="row between wrap"><h3>See it on a sample shopper</h3><select data-change="cl-shopper" style="width:auto" aria-label="Sample shopper">${SHOPPERS.map((x, i) => `<option value="${i}" ${i === CL.shopper ? 'selected' : ''}>${x[0]}</option>`).join('')}</select></div><div class="grid g2 mt12">${col(off, 'Priority off')}${col(on, 'Priority ' + s.lambda)}</div><p class="tiny muted mt8">“suits” is an internal 0–1 score for auditing. It is not a percentage and is never shown to shoppers.</p></div>
      <div class="col gap16"><div class="grid g2">${U.kpi('Aged stock on hand', FF.inrK(val), `at MRP · ${aged.length} styles`)}${U.kpi('At cost', FF.inrK((val * s.costRatio) / 100), `MRP × ${s.costRatio}% cost ratio`, { info: 'Many owners keep cost prices private, so aged value is worked out from MRP and a ratio you set in Settings → Store.' })}</div><div class="card"><h3>Where it sits</h3><div class="mt12">${CH.hbar(byBand, FF.inrK)}</div></div>
        <div class="card"><h3>When does stock count as aged?</h3><p class="small muted">Fresh → dead, in days</p>${Object.entries(s.aging).map(([k, v]) => `<div class="row mt8"><span class="grow">${{ western: 'Western wear', everyday: 'Everyday ethnic', occasion: 'Occasion wear' }[k]}</span><input type="number" min="15" max="400" value="${v[0]}" data-change="cl-age" data-lazy data-k="${k}" data-i="0" style="width:76px" aria-label="${k} fresh days"><span>→</span><input type="number" min="30" max="900" value="${v[1]}" data-change="cl-age" data-lazy data-k="${k}" data-i="1" style="width:76px" aria-label="${k} dead days"></div>`).join('')}</div></div></div>
      <div class="sec"><div class="sh"><h2>Pushes and offers</h2><button class="btn btn-s" data-act="cl-push">${FF.icon('plus')} New push</button></div><div class="card pad0">${db.pushes.filter((p) => p.active).map((p) => { const pd = FF.prod(p.pid); return `<div class="row" style="padding:10px 16px;border-bottom:1px solid var(--line)"><div class="thumb">${FF.garment(pd)}</div><div class="grow"><b>${esc(pd.name)}</b> ${U.badge(FF.cap(p.reason.toLowerCase().replace('_', ' ')), 'brass')}<div class="small muted">${p.offer ? 'Shopper sees “Store pick · offer”: ' + esc(p.offer) : 'No offer — ranks higher only where it suits; no label needed'}${p.spiff ? ' · staff incentive ' + FF.inr(p.spiff) : ''} · until ${FF.fmtDate(p.until)}</div></div><button class="btn btn-s" data-act="cl-end" data-id="${p.id}">End</button></div>`; }).join('') || U.empty('bolt', 'No active pushes', 'Push a piece you want seen: an owner pick, an overstock, or a festive leftover with an offer.')}</div></div>
      <div class="sec"><div class="sh"><h2>Aged stock</h2><span class="small muted">oldest first</span></div>${U.table('aged', [{ k: 'name', l: 'Piece', html: (p) => `<div class="row"><div class="thumb">${FF.garment(p)}</div><div><b>${esc(p.name)}</b><div class="small muted mono">${p.id} · ${p.rack}</div></div></div>` }, { k: 'age', l: 'In stock', sort: (p) => FF.ageDays(p), html: (p) => U.ageBadge(p) }, { k: 'q', l: 'Pieces', r: 1, html: (p) => FF.stockTotal(p) }, { k: 'val', l: 'Value at MRP', r: 1, sort: (p) => p.mrp * FF.stockTotal(p), html: (p) => FF.inr(p.mrp * FF.stockTotal(p)) }, { k: 'imp', l: 'Shown · 7 days', r: 1, sort: (p) => p.imp7, html: (p) => p.imp7 }, { k: 'tip', l: 'Suggestion', html: (p) => (p.imp7 >= 15 ? `<span class="small warn b">Shown often, not selling — consider a markdown</span>` : p.imp7 <= 3 ? `<span class="small muted">Rarely shown — few shoppers it suits, or needs full intake photos</span>` : '<span class="small muted">—</span>') }, { k: 'a', l: '', html: (p) => (db.pushes.some((x) => x.pid === p.id && x.active) ? U.badge('Pushed', 'brass') : `<button class="btn btn-s" data-act="cl-push" data-pid="${p.id}">Push</button>`) }], aged, { sort: 'age', dir: -1, per: 8 })}</div>`; } });
  FF.onChange('cl-max', (v) => { FF.db.settings.maxBoost = +v; FF.audit('Max nudged in top 5 → ' + v, 'Merch policy'); FF.save(); FF.render(); });
  FF.onChange('cl-shopper', (v) => { CL.shopper = +v; FF.render(); });
  FF.onChange('cl-age', (v, el) => { const a = FF.db.settings.aging[el.dataset.k], n = Math.round(+v), i = +el.dataset.i; if (!(n > 0) || (i === 0 && n >= a[1]) || (i === 1 && n <= a[0])) { FF.toast('“Fresh” must be fewer days than “dead”', 'bad'); return FF.render(); } a[i] = n; FF.audit('Changed aging window', el.dataset.k, a.join(' → ')); FF.save(); FF.render(); FF.toast('Aging window saved', 'ok'); });
  FF.act('cl-push', (d) => { const list = FF.db.products.filter((p) => p.status === 'LIVE' && FF.stockTotal(p) > 0); FF.modal({ title: 'New push', body: `<form id="pf2" data-submit="cl-push-save" class="col">${U.field('Piece', `<select name="pid" required>${list.map((p) => `<option value="${p.id}" ${p.id === d.pid ? 'selected' : ''}>${esc(p.name)} · ${p.id} · ${FF.ageDays(p)} d</option>`).join('')}</select>`)}<div class="grid g2">${U.field('Reason', `<select name="reason"><option value="CLEARANCE">Clearance</option><option value="OVERSTOCK">Overstock</option><option value="OWNER_PICK">Owner pick</option></select>`)}${U.field('Runs until', `<input name="until" type="date" required min="${FF.day(Date.now() + FF.DAY)}" value="${FF.day(Date.now() + 14 * FF.DAY)}">`)}</div>${U.field('Offer shown to shoppers (optional)', '<input name="offer" maxlength="40" placeholder="e.g. Festive leftover · 10% off">', 'If you write an offer, the piece is always labelled “Store pick · offer”. That honesty is not optional.')}${U.field('Staff incentive per piece (₹, optional)', '<input name="spiff" type="number" min="0" max="5000" step="50">')}</form>`, footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-p" form="pf2">Start push</button>` }); });
  FF.act('cl-push-save', (f) => { FF.db.pushes = FF.db.pushes.filter((p) => !(p.pid === f.pid && p.active)); FF.db.pushes.push({ id: FF.uid('pu'), pid: f.pid, reason: f.reason, offer: f.offer, spiff: f.spiff || 0, until: new Date(f.until).getTime() + FF.DAY, active: true }); FF.prod(f.pid).offer = f.offer || null; FF.audit('Started push', f.pid, f.offer || f.reason); FF.save(); FF.closeOverlay(); FF.render(); FF.toast('Push started', 'ok'); });
  FF.act('cl-end', (d) => { const p = FF.db.pushes.find((x) => x.id === d.id); p.active = false; FF.prod(p.pid).offer = null; FF.audit('Ended push', p.pid); FF.save(); FF.render(); FF.toast('Push ended', 'ok'); });

  /* ---------- demand gaps ---------- */
  const G = { show: 'open' };
  FF.page('gaps', { title: 'Demand gaps', icon: 'target', roles: R.MGR, render: () => { const rows = FF.db.gaps.filter((g) => g.status === G.show).sort((a, b) => b.count - a.count); FF.db.gaps.forEach((g) => { g.fresh = false; });
    return `<div class="ph1"><div><h1>Demand gaps</h1><p>What shoppers asked for that you could not show them — fewer than three suitable pieces in their size, budget and occasion. Read it as a buying list. ${U.demo('Demo counts')}</p></div><div class="row wrap">${U.seg('g-show', [['open', 'Open'], ['ordered', 'Ordered'], ['dismissed', 'Dismissed']], G.show)}<button class="btn" data-act="g-export">${FF.icon('download')} Export</button></div></div>
      <div class="col">${rows.map((g) => `<div class="card row wrap gap16"><div class="kpi" style="border:0;padding:0;min-width:92px"><div class="k-v">${g.count}</div><div class="k-s">shopper${g.count === 1 ? '' : 's'}</div></div><div class="grow" style="min-width:220px"><div class="serif" style="font-size:19px">wanted ${g.occasion !== 'any' ? esc(g.occasion) + ' ' : ''}${esc(FF.catName(g.cat).toLowerCase())}${g.size && g.size !== 'any' && g.size !== 'FREE' ? ' in ' + esc(g.size) : ''}${g.budget ? ' under ' + FF.inr(g.budget) : ''}${g.palette && g.palette !== 'any' && g.palette !== 'unknown' ? ' in ' + esc(g.palette) + ' colours' : ''}</div><div class="small muted mt4">You had ${g.had} suitable piece${g.had === 1 ? '' : 's'} to show${g.reason ? ' · ' + esc(g.reason) : ''}.</div></div>${g.status === 'open' ? `<div class="row"><button class="btn btn-s" data-act="g-set" data-id="${g.id}" data-s="dismissed">Not for us</button><button class="btn btn-s btn-p" data-act="g-set" data-id="${g.id}" data-s="ordered">Mark as ordered</button></div>` : `<button class="btn btn-s" data-act="g-set" data-id="${g.id}" data-s="open">Reopen</button>`}</div>`).join('') || `<div class="card">${U.empty('target', 'Nothing here', G.show === 'open' ? 'Every shopper found at least three suitable pieces.' : 'No gaps with this status.')}</div>`}</div>
      <div class="sec"><div class="sh"><h2>“Tell me when it arrives”</h2><span class="small muted">shoppers who opted in to one WhatsApp message</span></div><div class="card pad0">${FF.db.notify.map((n) => `<div class="row between" style="padding:10px 16px;border-bottom:1px solid var(--line)"><span>${esc(n.want)}</span><span class="small muted mono">${n.phone} · ${FF.fmtDate(n.at)}</span></div>`).join('') || U.empty('wa', 'No requests yet', 'When nothing matches, the shopper can leave a number for a single message.')}</div></div>`; } });
  FF.act('g-show', (d) => { G.show = d.v; FF.render(); });
  FF.act('g-set', (d) => { const g = FF.db.gaps.find((x) => x.id === d.id); g.status = d.s; FF.audit('Demand gap → ' + d.s, FF.catName(g.cat) + ' ' + g.size); FF.save(); FF.render(); FF.toast(d.s === 'ordered' ? 'Marked as ordered' : d.s === 'open' ? 'Reopened' : 'Dismissed', 'ok'); });
  FF.act('g-export', () => FF.download('buying-list.csv', FF.csv([['Shoppers', 'Category', 'Size', 'Occasion', 'Budget', 'Palette', 'We had', 'Status']].concat(FF.db.gaps.map((g) => [g.count, FF.catName(g.cat), g.size, g.occasion, g.budget, g.palette, g.had, g.status])))));

  /* ---------- team ---------- */
  FF.page('team', { title: 'Team', icon: 'star', roles: R.FLOOR, render: () => { const from = Date.now() - 30 * FF.DAY, me = FF.me(), rows = FF.db.staff.filter((s) => s.active && ['STAFF', 'MANAGER'].includes(s.role)).map((s) => { const V = FF.db.visits.filter((v) => v.staff === s.id && v.at >= from), S = FF.db.sales.filter((x) => x.staff === s.id && x.at >= from && x.visit), lines = S.flatMap((x) => x.lines), aged = lines.filter((l) => l.aged && l.rec).length; return { s, visits: V.length, sales: FF.sum(S, (x) => x.total), bills: S.length, aged, spiff: aged * 100 + FF.sum(lines, (l) => { const p = FF.db.pushes.find((x) => x.pid === l.pid && x.active); return p && p.spiff ? p.spiff : 0; }), conv: V.length ? S.length / V.length : 0 }; }).sort((a, b) => b.sales - a.sales);
    return `<div class="ph1"><div><h1>Team</h1><p>FitFirst is the salesperson's tool: every sale they help make carries their name, and selling aged pieces earns an incentive. Last 30 days. ${U.demo()}</p></div></div>
      <div class="split"><div>${U.table('team', [{ k: 'n', l: 'Salesperson', html: (r) => `<div class="row"><span class="avatar">${r.s.code}</span><b>${esc(r.s.name)}</b>${r.s.id === me.id ? ' ' + U.badge('You', 'ink') : ''}</div>` }, { k: 'v', l: 'Shoppers helped', r: 1, sort: (r) => r.visits, html: (r) => r.visits }, { k: 'c', l: 'Ended in a sale', r: 1, sort: (r) => r.conv, html: (r) => FF.pct(r.bills, r.visits) }, { k: 's', l: 'Sales in their name', r: 1, sort: (r) => r.sales, html: (r) => FF.inr(r.sales) }, { k: 'a', l: 'Aged pieces sold', r: 1, sort: (r) => r.aged, html: (r) => r.aged }, { k: 'i', l: 'Incentive', r: 1, sort: (r) => r.spiff, html: (r) => `<b>${FF.inr(r.spiff)}</b>` }], rows, { sort: 's', dir: -1 })}<p class="tiny muted mt8">Credit needs proof: a scanned QR, the code on the bill, or a sale recorded from the shopper's visit. Incentive = ₹100 per aged recommended piece plus any push incentive.</p></div>
      <div class="card"><h3>Sales through FitFirst</h3><div class="mt12">${CH.hbar(rows.map((r) => ({ l: r.s.name, v: r.sales })), FF.inrK)}</div><hr><h3>10-minute training script</h3><ol class="small" style="padding-left:18px;margin:8px 0 0;display:flex;flex-direction:column;gap:4px"><li>Open the queue. Claim the shopper who has waited longest.</li><li>Read their picks; the rack code tells you where each piece is.</li><li>Use the “Say” line — it is why the piece suits them.</li><li>Tap Tried, Rejected (one reason) or Add to bill.</li><li>At the counter, scan their QR. The sale is yours.</li></ol></div></div>`; } });

  /* ---------- pilot ---------- */
  FF.page('pilot', { title: 'Pilot scorecard', icon: 'flag', roles: R.MGR, render: () => { const p = FF.db.settings.pilot, s = FF.db.settings, days = Math.round((Date.now() - p.start) / FF.DAY), m = FF.metrics(days), owner = FF.me().role === 'OWNER';
    const lift = m.baseBasket ? (m.basket / m.baseBasket - 1) * 100 : null, conv = m.sessions ? (m.recBuy / m.sessions) * 100 : null, usage = m.usage == null ? null : m.usage * 100, enough = m.sessions >= 100 && m.baseN >= 60;
    const rows = [['Average bill value vs before', lift, p.basketLift, lift == null ? 'No baseline bills' : `${FF.inr(m.basket)} with FitFirst vs ${FF.inr(m.baseBasket)} before (${m.baseN} bills)`], ['Consultations that bought a recommended piece', conv, p.recConv, `${m.recBuy} of ${m.sessions} consultations`], ['Shoppers who used FitFirst', usage, p.usage, usage == null ? 'Log footfall below to measure this' : `${m.sessions} consultations of ${m.footfall} people through the door`]];
    const pass = rows.every((r) => r[1] != null && r[1] >= r[2]), verdict = !enough ? ['Collecting data', 'b-warn', 'Needs at least 100 consultations and 60 baseline bills before a verdict is fair.'] : pass ? ['Meeting every threshold', 'b-ok', 'All three agreed numbers are being met so far.'] : ['Below threshold', 'b-bad', 'At least one agreed number is not being met. The thresholds do not move.'];
    return `<div class="ph1"><div><h1>Pilot scorecard</h1><p>The numbers agreed in writing before go-live. If they are not met, we accept FitFirst is not working in this shop. ${U.demo('Demo numbers')}</p></div><span class="badge ${verdict[1]}" style="font-size:14px;padding:6px 14px">${verdict[0]}</span></div>
      <div class="card"><div class="row between wrap"><div><h3>Week ${Math.min(p.weeks, Math.floor(days / 7) + 1)} of ${p.weeks}</h3><p class="small muted">${verdict[2]}</p></div>${p.locked ? `<span class="badge b-ok">${FF.icon('lock')} Thresholds locked ${FF.fmtDate(p.lockedAt)}</span>` : owner ? `<button class="btn btn-p btn-s" data-act="pl-lock">${FF.icon('lock')} Lock thresholds</button>` : U.badge('Not locked yet', 'warn')}</div><div class="meter mt12"><i style="width:${Math.min(100, (days / (p.weeks * 7)) * 100)}%"></i></div>
        <div class="col gap16 mt24">${rows.map(([l, v, t, sub], i) => `<div><div class="row between wrap"><b>${l}</b><span class="num"><b class="${v == null ? 'muted' : v >= t ? 'ok' : 'bad'}">${v == null ? 'Not measurable yet' : (i === 0 && v >= 0 ? '+' : '') + v.toFixed(1) + '%'}</b> <span class="muted">· target ${i === 0 ? '+' : ''}${p.locked ? t + '%' : `<input type="number" min="1" max="100" value="${t}" data-change="pl-t" data-lazy data-k="${['basketLift', 'recConv', 'usage'][i]}" style="width:64px;display:inline-block;min-height:28px;padding:0 6px" aria-label="Target for ${l}">%`}</span></span></div><div class="meter mt8" style="position:relative;overflow:visible"><i style="width:${v == null ? 0 : FF.clamp((v / (t * 1.6)) * 100, 2, 100)}%;background:${v != null && v >= t ? 'var(--ok)' : 'var(--ink)'}"></i><span style="position:absolute;left:${100 / 1.6}%;top:-4px;bottom:-4px;width:2px;background:var(--brass)" title="Target"></span></div><div class="small muted mt4">${sub}</div></div>`).join('')}</div></div>
      <div class="grid g2 stack sec"><div class="card"><h3>The aged-stock measure</h3><dl class="kv mt12"><dt>Aged stock cleared</dt><dd><b>${FF.inr(m.agedCleared)}</b></dd><dt>Control group</dt><dd>${s.holdout}% of shoppers get no old-stock nudge ${p.locked ? '(locked)' : ''}</dd><dt>Boosted visits</dt><dd>${m.nBoost} · aged piece bought in ${(m.rb * 100).toFixed(1)}%</dd><dt>Control visits</dt><dd>${m.nHold} · aged piece bought in ${(m.rh * 100).toFixed(1)}%</dd><dt>Measured lift</dt><dd>${m.lift == null ? 'Not enough control visits yet (20 needed)' : `<b>${m.lift >= 0 ? '+' : ''}${Math.round(m.lift * 100)}%</b>`}</dd></dl><a class="link small" href="#/insights">Open results</a></div>
        <div class="card"><h3>Log footfall</h3><p class="small muted">People through the door, from the counter or a clicker. Without it “usage” cannot be measured.</p><form data-submit="pl-foot" class="row wrap top mt12"><div class="field" style="width:150px"><input name="date" type="date" required max="${FF.day(Date.now())}" value="${FF.day(Date.now())}" aria-label="Date"></div><div class="field" style="width:110px"><input name="footfall" type="number" required min="0" max="5000" placeholder="People" aria-label="Footfall" data-msg="How many people came in?"></div><div class="field grow" style="min-width:140px"><input name="note" placeholder="Note (optional)" maxlength="60" aria-label="Note"></div><button class="btn btn-p">Save</button></form></div></div>
      <div class="sec"><div class="sh"><h2>Daily log</h2><span class="small muted">before and during the pilot</span></div>${U.table('base', [{ k: 'd', l: 'Date', sort: (b) => b.date, html: (b) => b.date }, { k: 'k', l: 'Period', html: (b) => (b.kiosk ? U.badge('FitFirst live', 'ok') : U.badge('Baseline')) }, { k: 'f', l: 'Footfall', r: 1, html: (b) => b.footfall }, { k: 's', l: 'Bills', r: 1, html: (b) => FF.db.sales.filter((x) => FF.day(x.at) === b.date).length }, { k: 'r', l: 'Revenue', r: 1, html: (b) => FF.inr(FF.sum(FF.db.sales.filter((x) => FF.day(x.at) === b.date), (x) => x.total)) }, { k: 'n', l: 'Note', html: (b) => esc(b.note || '') }], FF.db.baseline, { sort: 'd', dir: -1, per: 8 })}</div>`; } });
  FF.onChange('pl-t', (v, el) => { const n = Math.round(+v); if (!(n >= 1 && n <= 100)) { FF.toast('Enter a percentage between 1 and 100', 'bad'); return FF.render(); } FF.db.settings.pilot[el.dataset.k] = n; FF.save(); FF.render(); });
  FF.act('pl-lock', () => { const p = FF.db.settings.pilot; FF.confirm('Lock the thresholds?', `${p.basketLift}% bill value · ${p.recConv}% recommended conversion · ${p.usage}% usage. Once locked they cannot be changed by anyone — that is the point.`, 'Lock for the pilot', () => { p.locked = true; p.lockedAt = Date.now(); FF.audit('Locked kill threshold', 'Pilot', `${p.basketLift}% · ${p.recConv}% · ${p.usage}%`); FF.save(); FF.render(); FF.toast('Thresholds locked', 'ok'); }); });
  FF.act('pl-foot', (f) => { const ex = FF.db.baseline.find((b) => b.date === f.date); if (ex) Object.assign(ex, { footfall: f.footfall, note: f.note }); else FF.db.baseline.push({ date: f.date, kiosk: new Date(f.date).getTime() >= FF.db.settings.pilot.start - FF.DAY, footfall: f.footfall, note: f.note }); FF.audit('Logged footfall', f.date, String(f.footfall)); FF.save(); FF.render(); FF.toast(ex ? 'Updated ' + f.date : 'Saved', 'ok'); });
})();
